INSERT IGNORE INTO `subcategories` (`category_id`, `name`, `name_en`, `slug`) SELECT c.`id`, 'Підтримка клієнтів', 'Customer Support', 'customer-support' FROM `categories` c WHERE c.`slug` = 'business-marketing' LIMIT 1;

SET @uid = (SELECT `id` FROM `users` WHERE `email` = 'whitevelvetelf@gmail.com' LIMIT 1);

-- Zendesk — Підтримка клієнтів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'zendesk.com' OR LOWER(`name`) = LOWER('Zendesk'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Zendesk', NULL, 'https://www.zendesk.com', NULL, NULL, 'Платформа служби підтримки з AI-агентами, що самі закривають звернення, і Copilot для операторів: тікети, чат, месенджери, телефонія та база знань в одному місці.', 'A customer service platform with AI agents that resolve requests on their own and a Copilot for human agents: tickets, chat, messaging, voice and a knowledge base in one place.', 'Zendesk — одна з найпоширеніших платформ клієнтської підтримки. Вона об''єднує тікети з email, чат, месенджери й телефонію, базу знань і маршрутизацію звернень. AI-агенти відповідають клієнтам і самостійно закривають типові звернення (кожен тариф включає кілька автоматичних вирішень на оператора, далі — $1,50–2 за вирішення), а Copilot підказує операторам відповіді, сортує звернення й допомагає адміністраторам. До Zendesk також приєдналася AI-платформа Forethought. Тарифи за оператора на місяць при річній оплаті: Support Team — $19; Suite Team — $55; Suite Professional — $115; Enterprise — за запитом; модуль Copilot — $50. Помісячна оплата дорожча.', 'Zendesk is one of the most widely used customer support platforms. It brings together email tickets, chat, messaging and voice, a knowledge base and request routing. AI agents answer customers and resolve common requests on their own (each plan includes a few automated resolutions per agent, then $1.50–2 per resolution), while Copilot suggests replies to human agents, triages requests and guides admins. The Forethought AI platform has joined Zendesk. Plans per agent a month billed annually: Support Team — $19; Suite Team — $55; Suite Professional — $115; Enterprise on request; the Copilot add-on is $50. Monthly billing costs more.', 'AI-агенти для автоматичного вирішення звернень
Copilot для операторів і адміністраторів
Тікети, чат, месенджери й телефонія
База знань і маршрутизація', 'AI agents that resolve requests automatically
Copilot for agents and admins
Tickets, chat, messaging and voice
Knowledge base and routing', 'Служби підтримки компаній будь-якого розміру — від стартапів до великих корпорацій.', 'Customer support teams at companies of any size — from startups to large enterprises.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'zendesk.com' OR LOWER(`name`) = LOWER('Zendesk')) ORDER BY `id` LIMIT 1);
