INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Zendesk is one of the most widely used customer support platforms. It brings together email tickets, chat, messaging and voice, a knowledge base and request routing. AI agents answer customers and resolve common requests on their own (each plan includes a few automated resolutions per agent, then $1.50–2 per resolution), while Copilot suggests replies to human agents, triages requests and guides admins. The Forethought AI platform has joined Zendesk. Plans per agent a month billed annually: Support Team — $19; Suite Team — $55; Suite Professional — $115; Enterprise on request; the Copilot add-on is $50. Monthly billing costs more.', 'manual' FROM DUAL WHERE @new = 1;
