SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'freshworks.com/freshdesk' OR LOWER(`name`) = LOWER('Freshdesk'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Freshdesk', NULL, 'https://www.freshworks.com/freshdesk/', NULL, NULL, 'Хелпдеск від Freshworks з AI-агентом Freddy, що відповідає клієнтам, і Freddy Copilot для операторів: тікети, портал клієнтів, база знань і аналітика.', 'A helpdesk from Freshworks with the Freddy AI Agent that answers customers and Freddy Copilot for human agents: tickets, a customer portal, a knowledge base and analytics.', 'Freshdesk — система підтримки клієнтів від Freshworks. Вона збирає звернення в спільну скриньку тікетів, дає клієнтський портал і базу знань, налаштовувані звіти, SLA та маршрутизацію. AI-агент Freddy самостійно відповідає клієнтам (500 сесій включено в кожен тариф, далі $49 за 100 сесій), Freddy AI Copilot допомагає операторам з відповідями, аналізом настрою та живим перекладом, а Freddy AI Insights у тарифі Enterprise шукає першопричини проблем. Тарифи за оператора на місяць при річній оплаті: Growth — $19; Pro — $55; Enterprise — $89; Copilot — +$29. Є 14-денний пробний період.', 'Freshdesk is the customer support system from Freshworks. It gathers requests into a shared ticket inbox and provides a customer portal and knowledge base, custom reports, SLAs and routing. The Freddy AI Agent answers customers on its own (500 sessions included in every plan, then $49 per 100 sessions), Freddy AI Copilot helps agents with replies, sentiment analysis and live translation, and Freddy AI Insights on Enterprise finds root causes of issues. Plans per agent a month billed annually: Growth — $19; Pro — $55; Enterprise — $89; Copilot — +$29. There is a 14-day free trial.', 'AI-агент Freddy (500 сесій у кожному тарифі)
Freddy Copilot: підказки, настрій, переклад
Тікети, портал клієнтів, база знань
SLA, маршрутизація й дашборди', 'Freddy AI Agent (500 sessions on every plan)
Freddy Copilot: suggestions, sentiment, translation
Tickets, customer portal, knowledge base
SLAs, routing and dashboards', 'Служби підтримки малого й середнього бізнесу, яким потрібен простий хелпдеск з AI.', 'Support teams at small and mid-sized businesses that want a straightforward helpdesk with AI.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
