INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Gorgias', NULL, 'https://www.gorgias.com', NULL, NULL, 'Хелпдеск для інтернет-магазинів (особливо на Shopify) з AI-агентом, що сам відповідає покупцям у пошті, чаті, SMS, соцмережах і телефоні.', 'A helpdesk for online stores (especially on Shopify) with an AI Agent that answers shoppers on its own across email, chat, SMS, social media and phone.', 'Gorgias створено для e-commerce. Він збирає звернення покупців з пошти, чату, SMS, телефону й соцмереж в одну стрічку і орієнтований насамперед на магазини на Shopify. AI-агент доступний на всіх тарифах і самостійно вирішує типові запитання — про доставку, повернення, товари; платите лише тоді, коли він закрив розмову ($1 за автоматичну взаємодію при помісячній оплаті, $0,90 — при річній). Тарифи хелпдеску (помісячно): Starter — $10 (50 тікетів); Basic — $60 (300); Pro — $360 (2 000); Advanced — $900 (5 000); Enterprise — за запитом.', 'Gorgias is built for e-commerce. It gathers shopper requests from email, chat, SMS, phone and social media into one feed and is aimed primarily at Shopify stores. The AI Agent is available on every plan and resolves common questions — about shipping, returns and products — on its own; you pay only when it closes a conversation ($1 per automated interaction billed monthly, $0.90 billed annually). Helpdesk plans (monthly): Starter — $10 (50 tickets); Basic — $60 (300); Pro — $360 (2,000); Advanced — $900 (5,000); Enterprise on request.', 'AI-агент для типових запитань покупців
Пошта, чат, SMS, телефон і соцмережі в одній стрічці
Орієнтація на магазини Shopify
Оплата AI лише за вирішені розмови', 'AI Agent for common shopper questions
Email, chat, SMS, phone and social in one feed
Built for Shopify stores
Pay for AI only when it resolves a conversation', 'Інтернет-магазини та DTC-бренди, особливо на Shopify.', 'Online stores and DTC brands, especially on Shopify.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
