SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'decagon.ai' OR LOWER(`name`) = LOWER('Decagon'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Decagon', NULL, 'https://decagon.ai', NULL, NULL, 'Платформа AI-агентів для підтримки клієнтів у чаті, email і голосом: сценарії задаються звичайною мовою, є тестування, A/B-експерименти й аналітика.', 'An AI agent platform for customer support in chat, email and voice: workflows are defined in plain language, with testing, A/B experiments and analytics built in.', 'Decagon допомагає великим компаніям будувати й масштабувати AI-агентів для обслуговування клієнтів. Поведінку агента описують звичайною мовою у вигляді «процедур» (Agent Operating Procedures), без складного програмування, а єдиний шар інтелекту працює в чаті, email і голосових каналах. У платформу вбудовано тестування, A/B-експерименти, контроль якості та аналітику, що підказує, як покращити агента. Серед клієнтів — Deutsche Telekom, American Airlines, Delta, Duolingo, Chime та Ticketmaster. Ціни не опубліковано — їх обговорюють під час демонстрації.', 'Decagon helps large companies build and scale AI agents for customer service. Agent behaviour is described in plain language as ''Agent Operating Procedures'', without complex coding, and a single intelligence layer works across chat, email and voice. Testing, A/B experiments, quality assurance and analytics that show how to improve the agent are built in. Customers include Deutsche Telekom, American Airlines, Delta, Duolingo, Chime and Ticketmaster. Pricing is not published — it is discussed during a demo.', 'AI-агенти в чаті, email і голосом
Сценарії звичайною мовою (AOP)
Тестування й A/B-експерименти
Контроль якості та аналітика', 'AI agents in chat, email and voice
Workflows in plain language (AOPs)
Testing and A/B experiments
Quality assurance and analytics', 'Великі компанії з високим потоком звернень: фінанси, авіація, ритейл, технології.', 'Large companies with high request volumes: finance, travel, retail and technology.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
