-- Sierra — Підтримка клієнтів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sierra.ai' OR LOWER(`name`) = LOWER('Sierra'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Sierra', NULL, 'https://sierra.ai', NULL, NULL, 'Платформа розмовних AI-агентів для клієнтського сервісу великих брендів: чат, SMS, WhatsApp, email, голос і ChatGPT, з оплатою за досягнутий результат.', 'A conversational AI agent platform for the customer experience of large brands: chat, SMS, WhatsApp, email, voice and ChatGPT, with outcome-based pricing.', 'Sierra дає великим компаніям змогу створювати AI-агентів, які спілкуються з клієнтами від імені бренду й доводять запити до результату. Інструмент Ghostwriter будує готового агента з регламентів, записів розмов чи опису звичайною мовою, Agent Studio дає змогу керувати агентами й стежити за ними, а розділ Insights — аналізувати розмови, виявляти проблеми, проводити експерименти й відстежувати дії агента. Агенти працюють у чаті, SMS, WhatsApp, email, голосом і навіть у ChatGPT. Платформа має сертифікації SOC 2 Type II, ISO 27001, HIPAA, PCI DSS та інші. Серед клієнтів — Gap, Hyatt, Uber, SiriusXM, Vanguard і Santander. Оплата залежить від досягнутих результатів, а не від кількості розмов; ціни — за запитом.', 'Sierra lets large companies build AI agents that talk to customers on the brand''s behalf and carry requests through to an outcome. Ghostwriter builds a ready agent from SOPs, conversation transcripts or a plain-English description, Agent Studio lets you manage and monitor agents, and Insights lets you analyse conversations, spot issues, run experiments and track agent actions. Agents work in chat, SMS, WhatsApp, email, voice and even ChatGPT. The platform holds SOC 2 Type II, ISO 27001, HIPAA, PCI DSS and other certifications. Customers include Gap, Hyatt, Uber, SiriusXM, Vanguard and Santander. Pricing is outcome-based rather than per conversation and is available on request.', 'Ghostwriter: агент з регламентів чи опису
Чат, SMS, WhatsApp, email, голос і ChatGPT
Аналітика, моніторинг і експерименти
Оплата за результат', 'Ghostwriter: an agent from SOPs or a description
Chat, SMS, WhatsApp, email, voice and ChatGPT
Analytics, monitoring and experiments
Outcome-based pricing', 'Великі бренди й корпорації з масовим клієнтським сервісом.', 'Large brands and enterprises with high-volume customer service.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
